/* Widows Sons MRA — Chapter Hellas
   The letterhead faces, carried into the PDF: Cinzel for the display
   lines, EB Garamond for everything else. Both are subset to Latin and
   Greek, so the Greek titles of the offices set as they should.
   Cinzel and EB Garamond are licensed under the SIL Open Font License. */
window.WSFonts = (function(){
  var TTF = {
    'WSGaramond|normal': '',
    'WSGaramond|bold': '',
    'WSGaramond|italic': '',
    'WSCinzel|bold': '',
  };
  var done = false;
  /* Register the faces with a jsPDF document. */
  function register(doc){
    for(var key in TTF){
      var bits = key.split('|');           /* family | style */
      var file = bits[0] + '-' + bits[1] + '.ttf';
      doc.addFileToVFS(file, TTF[key]);
      doc.addFont(file, bits[0], bits[1]);
    }
    done = true;
    return doc;
  }
  return { register:register, ready:function(){ return done; } };
})();
